package com.example.demo;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/greetings")
public class GreetingController {
    public record GreetingRequest(@NotBlank String name) {}
    public record GreetingResponse(String message) {}

    @PostMapping
    public GreetingResponse greet(@Valid @RequestBody GreetingRequest request) {
        return new GreetingResponse("Hello, " + request.name());
    }

    @GetMapping("/{id}")
    public GreetingResponse find(@PathVariable("id") long id) {
        if (id != 1) {
            throw new GreetingNotFoundException();
        }
        return new GreetingResponse("Hello, Ada");
    }
}

class GreetingNotFoundException extends RuntimeException {}

package com.example.demo;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class GreetingErrors {
    @ExceptionHandler(GreetingNotFoundException.class)
    public ProblemDetail missing(GreetingNotFoundException exception) {
        return ProblemDetail.forStatusAndDetail(
            HttpStatus.NOT_FOUND, "Greeting was not found");
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail invalid(MethodArgumentNotValidException exception) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(
            HttpStatus.BAD_REQUEST, "Request fields failed validation");
        problem.setProperty("fields", exception.getBindingResult().getFieldErrors()
            .stream().map(error -> error.getField()).distinct().toList());
        return problem;
    }
}

package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {
    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}
